package dev.zomboid.decor;
import java.util.*;import dev.zomboid.turretpower.Checks.*;
public class BedChecks {
 static int checks;static void ok(boolean b,String m){checks++;if(!b)throw new AssertionError(m);}
 public static class Result{public Optional<Problem> left(){return Optional.empty();}}
 public static class Problem{public Object getMessage(){return "unsafe";}}
 public static class SpawnEvent{Object player,pos;boolean canceled;SpawnEvent(Object p,Object pos){player=p;this.pos=pos;}public Object getEntity(){return player;}public Object getNewSpawn(){return pos;}public void setCanceled(boolean c){canceled=c;}}
 public static class Sleeper {public W w;public Object dim="overworld",pos=new P(20,64,20);public float angle=27f;public boolean forced=true,fail;public Optional<Object> sleeping=Optional.empty();public List<Object> messages=new ArrayList<>();public int calls;Sleeper(W w){this.w=w;}public Object getRespawnDimension(){return dim;}public Object getRespawnPosition(){return pos;}public float getRespawnAngle(){return angle;}public boolean isRespawnForced(){return forced;}public Optional<Object> getSleepingPos(){return sleeping;}public Object startSleepInBed(Object p){calls++;setRespawnPosition("new",p,90f,false,true);if(fail)throw new IllegalStateException("test sleep hook failure");sleeping=Optional.of(p);return new Result();}public void setRespawnPosition(Object d,Object p,float a,boolean f,boolean send){SpawnEvent event=new SpawnEvent(this,p);Beds.spawn(event);if(event.canceled)return;dim=d;pos=p;angle=a;forced=f;}public void displayClientMessage(Object text,boolean bar){messages.add(text);}}
 public static void main(String[]args){W w=new W();P p=new P(0,64,0);S bed=new S("doomsday_decoration:bed");Sleeper player=new Sleeper(w);Object old=player.pos;w.players.add(player);
  ok(Beds.use(bed,w,p,player),"bed interaction consumed");ok(player.calls==1&&player.sleeping.get().equals(p),"sleep called");ok(player.pos==old&&player.dim.equals("overworld")&&player.angle==27&&player.forced,"respawn position dimension angle and forced flag preserved");
  Sleeper second=new Sleeper(w);ok(Beds.use(bed,w,p,second)&&second.calls==0&&!second.messages.isEmpty(),"occupied bed rejected");player.sleeping=Optional.empty();w.players.clear();
  player.pos=null;player.forced=false;Beds.use(new S("doomsday_decoration:medical_bed"),w,p,player);ok(player.pos==null&&!player.forced,"unset spawn stays unset");player.sleeping=Optional.empty();
  player.fail=true;boolean threw=false;try{Beds.use(bed,w,p,player);}catch(IllegalStateException expected){threw=true;}ok(threw&&player.pos==null&&player.dim.equals("overworld"),"restore spawn even if sleep listener throws");player.fail=false;
  player.setRespawnPosition("outside",old,15,true,false);ok(player.dim.equals("outside")&&player.pos==old,"spawn events outside sleep untouched");w.bedWorks=false;int n=player.calls;Beds.use(bed,w,p,player);ok(player.calls==n,"bed-invalid dimension rejected without explosion");w.bedWorks=true;w.client=true;Beds.use(bed,w,p,player);ok(player.calls==n,"client does not run sleep");w.client=false;ok(!Beds.use(new S("doomsday_decoration:desk"),w,p,player),"other furniture unchanged");
  P door=new P(0,0,0),board=new P(1,0,0);for(String id:new String[]{"minecraft:glass","minecraft:glass_pane","minecraft:oak_door","doomsday_decoration:door_1","minecraft:iron_trapdoor"}){w.blocks.clear();w.blocks.put(door,new S(id));ok(Boards.factor(w,door)==1,"unboarded "+id);w.blocks.put(board,new S("doomsday_decoration:planking_0"));ok(Boards.factor(w,door)==2,"double resistance "+id);w.blocks.put(new P(-1,0,0),new S("doomsday_decoration:planking_1"));ok(Boards.factor(w,door)==2,"multiple boards do not multiply "+id);}
  w.blocks.clear();w.blocks.put(door,new S("minecraft:oak_door"));w.blocks.put(new P(0,1,0),new S("minecraft:oak_door"));w.blocks.put(new P(1,1,0),new S("doomsday_decoration:planking_0"));ok(Boards.factor(w,door)==2,"upper board reinforces lower door half");w.blocks.clear();w.blocks.put(door,new S("minecraft:stone"));ok(Boards.factor(w,door)==1,"ordinary walls unaffected");w.blocks.put(door,new S("minecraft:glass"));w.blocks.put(board,new S("doomsday_decoration:planking_0"));w.loaded=false;ok(Boards.factor(w,door)==1,"no chunk loading");
  w.loaded=true;ok(dev.zomboid.hordes.BarricadeLink.ticks(80,w,door)==160,"native Hordes .43 siege bridge doubles time");System.out.println("Beds and boards checks: "+checks);
 }
}
